UPDATE tours SET has_page = 1, summary = 'Nine days lodge to lodge across Bhutan, staying at the Amankora lodges in Paro, Thimphu, Punakha and Gangtey — a private circuit of the western valleys.', overview_title = 'Tour Overview', overview = 'Amankora is Bhutan''s best-known lodge circuit: a handful of intimate lodges set in the finest valleys, each built in the local style with rammed-earth walls, stoves and wide views. This journey links four of them — Paro, Thimphu, Punakha and Gangtey — into one unhurried circuit with a private guide and driver.

There is plenty of time to be still. The days are paced around a morning excursion and a long, restful afternoon at the lodge, so you move through the country without ever feeling hurried. It is a trip for travellers who want to see Bhutan well and sleep better than they thought possible in a mountain kingdom.', highlights = '["Stay in four Amankora lodges across the western valleys","Hike to Tiger’s Nest Monastery with a private blessing","Cross Dochula pass and visit Punakha Dzong","The Phobjikha valley and Gangtey Goenpa, home of the black-necked cranes","Private guide and driver for every excursion","Time at each lodge to rest, read or simply watch the valley"]', facts = '[{"icon":"pin","label":"Destinations","value":"Paro, Thimphu, Punakha, Gangtey"},{"icon":"sun","label":"Best Season","value":"March–May & September–November"},{"icon":"mountain","label":"Max Altitude","value":"3,000m — Dochula Pass and Gangtey"},{"icon":"bag","label":"Accommodation","value":"Amankora lodges in Paro, Thimphu, Punakha and Gangtey"},{"icon":"meal","label":"Meals","value":"Full board — breakfast, lunch, dinner"},{"icon":"truck","label":"Transport","value":"Private SUV with driver"}]', facts_note = 'Use this as a general guide to the journey. The itinerary is further customized around the season, your interests, group size and preferred duration once you enquire.', pack_title = 'What To Pack', pack_text = 'Lodges are comfortable but evenings are cool at altitude, so bring warm layers, a light jacket and a hat. Comfortable shoes for temple courtyards and the Tiger’s Nest path are essential.

Smart-casual clothing is fine for dinner. Bring sun protection and a camera with a zoom lens for the festivals, birds and valley views.', inclusions = '["Lodge stays at Amankora in Paro, Thimphu, Punakha and Gangtey","Meals as per the itinerary — breakfast, lunch and dinner","A private licensed cultural guide throughout","A private vehicle with driver for the whole journey","All monument and museum entrance fees"]', exclusions = '["International flights to and from Bhutan","The Sustainable Development Fee ($100 per person per night), billed separately","Travel insurance","Spa treatments, premium drinks and gratuities"]', faqs = '[{"question":"Which Amankora lodges are included?","answer":"This journey is designed around the Paro, Thimphu, Punakha and Gangtey lodges. Availability varies by season, and we confirm the exact lodges and dates when you enquire."},{"question":"How long are the drives?","answer":"Most drives are two to three hours, with stops. The longest is the return from Gangtey to Thimphu, about five hours, broken up with viewpoints and lunch."},{"question":"Is this journey suitable for older travellers?","answer":"Yes. Days are paced gently, the hike to Tiger’s Nest is optional, and the lodges make rest easy."}]', districts = '["Paro","Thimphu","Punakha","Wangdue Phodrang"]', cost_title = 'Package Cost', cost_text = 'On top of the Sustainable Development Fee of $100 per person per night (see our [Tariff page](/tariff)), there''s an additional cost covering accommodation, meals, entrance fees, your guide and a private tour vehicle. Send us an enquiry below and we''ll shape a package to your dates, budget and interests.', seo_description = 'Nine days lodge to lodge across Bhutan, staying at the Amankora lodges in Paro, Thimphu, Punakha and Gangtey — a private circuit of the western valleys.', updated_at = datetime('now') WHERE slug = 'amankora-journey';
DELETE FROM itinerary_days WHERE tour_id = (SELECT id FROM tours WHERE slug = 'amankora-journey');

UPDATE tours SET has_page = 1, summary = 'Nine days of slow travel through the western valleys, built around yoga, spa time, meditation and farm-to-table meals at the Six Senses lodges.', overview_title = 'Tour Overview', overview = 'This is a journey built to restore. Instead of ticking off monuments, the days are shaped around rest: morning yoga or meditation, a long walk, a hot stone bath, a treatment at the lodge spa, and meals made from local produce. In between, there is enough of Bhutan — a dzong, a monastery, a farmhouse lunch — to make you feel you have travelled.

The route links the Six Senses lodges in Thimphu, Punakha, Gangtey and Paro, each in a different landscape, so the change of scene is part of the wellbeing. It suits travellers who want a gentle pace, good food and quiet time, and it works especially well in spring and autumn.', highlights = '["Morning yoga and meditation sessions with local teachers","Hot stone baths and spa treatments at the lodges","Farm-to-table meals using produce from the valleys","Walk the Phobjikha valley with a naturalist guide","Time with monks for a guided meditation","Slow days at the lodges to rest, read or simply watch the valley"]', facts = '[{"icon":"pin","label":"Destinations","value":"Thimphu, Punakha, Gangtey, Paro"},{"icon":"sun","label":"Best Season","value":"March–May & September–November"},{"icon":"mountain","label":"Max Altitude","value":"2,900m — Phobjikha valley"},{"icon":"bag","label":"Accommodation","value":"Six Senses Bhutan lodges in Thimphu, Punakha, Gangtey and Paro"},{"icon":"meal","label":"Meals","value":"Full board — breakfast, lunch, dinner"},{"icon":"truck","label":"Transport","value":"Private SUV with driver"}]', facts_note = 'Use this as a general guide to the journey. The itinerary is further customized around the season, your interests, group size and preferred duration once you enquire.', pack_title = 'What To Pack', pack_text = 'Bring loose, comfortable clothing for yoga and meditation, plus warm layers for cool mountain evenings. Sturdy walking shoes are useful for the Phobjikha valley and temple courtyards.

The lodges provide robes and slippers. Bring a swimsuit for the baths and a small notebook if you like to write.', inclusions = '["Lodge stays at Six Senses Bhutan in Thimphu, Punakha, Gangtey and Paro","Meals as per the itinerary — breakfast, lunch and dinner","A private licensed cultural guide throughout","A private vehicle with driver for the whole journey","All monument and museum entrance fees"]', exclusions = '["International flights to and from Bhutan","The Sustainable Development Fee ($100 per person per night), billed separately","Travel insurance","Spa treatments, premium drinks and gratuities"]', faqs = '[{"question":"Do I need to have done yoga before?","answer":"Not at all. Sessions are suitable for all levels and your teacher adapts to the group."},{"question":"Are spa treatments included?","answer":"Spa treatments are not included in the package price, but we can add a treatment each day if you like. Tell us your preferences when you enquire."},{"question":"Can I travel solo on this journey?","answer":"Yes. A wellness journey works well for solo travellers, with a private guide to look after the details."}]', districts = '["Paro","Thimphu","Punakha","Wangdue Phodrang"]', cost_title = 'Package Cost', cost_text = 'On top of the Sustainable Development Fee of $100 per person per night (see our [Tariff page](/tariff)), there''s an additional cost covering accommodation, meals, entrance fees, your guide and a private tour vehicle. Send us an enquiry below and we''ll shape a package to your dates, budget and interests.', seo_description = 'Nine days of slow travel through the western valleys, built around yoga, spa time, meditation and farm-to-table meals at the Six Senses lodges.', updated_at = datetime('now') WHERE slug = 'six-senses-wellness-journey';
DELETE FROM itinerary_days WHERE tour_id = (SELECT id FROM tours WHERE slug = 'six-senses-wellness-journey');

UPDATE tours SET has_page = 1, summary = 'Five days between two COMO Uma properties — Paro and Punakha — with the Tiger’s Nest hike, Dochula pass and Punakha Dzong in between.', overview_title = 'Tour Overview', overview = 'This short luxury journey links two of Bhutan''s most admired hotels: COMO Uma Paro, set above the valley with views of the mountains, and COMO Uma Punakha, on the river in the warm southern valley. The two places feel very different and the drive between them crosses Dochula pass, so it makes a good first luxury circuit.

The days are structured around two or three excursions, always unhurried: the Tiger''s Nest climb from Paro, the dzong at Punakha, a village walk and, at both properties, plenty of time at the spa and pool. It suits couples and small families who want a taste of Bhutan in five days.', highlights = '["Two COMO Uma properties, in Paro and in Punakha","Hike to Tiger’s Nest Monastery, with a private blessing","Cross Dochula pass between the two valleys","Punakha Dzong and the Chimi Lhakhang walk","Spa and yoga time at both properties","Private guide and driver throughout"]', facts = '[{"icon":"pin","label":"Destinations","value":"Paro, Punakha"},{"icon":"sun","label":"Best Season","value":"March–May & September–November"},{"icon":"mountain","label":"Max Altitude","value":"3,120m — Taktsang Monastery"},{"icon":"bag","label":"Accommodation","value":"COMO Uma Paro and COMO Uma Punakha"},{"icon":"meal","label":"Meals","value":"Full board — breakfast, lunch, dinner"},{"icon":"truck","label":"Transport","value":"Private SUV with driver"}]', facts_note = 'Use this as a general guide to the journey. The itinerary is further customized around the season, your interests, group size and preferred duration once you enquire.', pack_title = 'What To Pack', pack_text = 'Bring comfortable walking shoes for the Tiger’s Nest path and village walks, plus a light jacket for cool evenings. Smart-casual clothing is fine for dinner. A swimsuit is useful for the pools.

Bring sun protection and a camera with a good zoom for the valley and the monastery.', inclusions = '["Stays at COMO Uma Paro and COMO Uma Punakha","Meals as per the itinerary — breakfast, lunch and dinner","A private licensed cultural guide throughout","A private vehicle with driver for the whole journey","All monument and museum entrance fees"]', exclusions = '["International flights to and from Bhutan","The Sustainable Development Fee ($100 per person per night), billed separately","Travel insurance","Spa treatments, premium drinks and gratuities"]', faqs = '[{"question":"How long is the drive between Paro and Punakha?","answer":"Around four hours, with a stop at Dochula pass for the views and tea."},{"question":"Can we skip the Tiger’s Nest hike?","answer":"Of course. It is optional, and the hotels offer plenty to do instead, from spa treatments to village walks."},{"question":"Can this be extended?","answer":"Easily. Many guests add a night in Thimphu or two nights in Gangtey. Tell us what you have in mind."}]', districts = '["Paro","Thimphu","Punakha"]', cost_title = 'Package Cost', cost_text = 'On top of the Sustainable Development Fee of $100 per person per night (see our [Tariff page](/tariff)), there''s an additional cost covering accommodation, meals, entrance fees, your guide and a private tour vehicle. Send us an enquiry below and we''ll shape a package to your dates, budget and interests.', seo_description = 'Five days between two COMO Uma properties — Paro and Punakha — with the Tiger’s Nest hike, Dochula pass and Punakha Dzong in between.', updated_at = datetime('now') WHERE slug = 'como-uma-paro-punakha';
DELETE FROM itinerary_days WHERE tour_id = (SELECT id FROM tours WHERE slug = 'como-uma-paro-punakha');

UPDATE tours SET has_page = 1, summary = 'Eight romantic days across Bhutan’s western valleys: private picnics, a temple blessing for couples and quiet evenings at the finest lodges.', overview_title = 'Tour Overview', overview = 'A honeymoon in Bhutan is quiet and unhurried. This journey links five lodges in Paro, Thimphu, Punakha and Gangtey with private excursions, long lunches and plenty of time together. Nothing is rushed and the programme is built around the two of you: a picnic by the river, a blessing at Chimi Lhakhang, a private dinner at the lodge.

It is a journey for couples celebrating a wedding, an anniversary or simply time together. We pick lodges with the best views and the most privacy, and your guide and driver are on hand throughout but never in the way.', highlights = '["Private picnic beside a river in Punakha","A couple’s blessing at Chimi Lhakhang, the temple of fertility","Hike to Tiger’s Nest, optional and entirely at your own pace","Candlelit private dinner at a lodge","Spa time and slow mornings at each stop","Private guide and driver, with plenty of space for the two of you"]', facts = '[{"icon":"pin","label":"Destinations","value":"Paro, Thimphu, Punakha, Gangtey"},{"icon":"sun","label":"Best Season","value":"March–May & September–November"},{"icon":"mountain","label":"Max Altitude","value":"2,900m — Phobjikha valley"},{"icon":"bag","label":"Accommodation","value":"Luxury lodges with private villas"},{"icon":"meal","label":"Meals","value":"Full board — breakfast, lunch, dinner"},{"icon":"truck","label":"Transport","value":"Private SUV with driver"}]', facts_note = 'Use this as a general guide to the journey. The itinerary is further customized around the season, your interests, group size and preferred duration once you enquire.', pack_title = 'What To Pack', pack_text = 'Bring smart-casual clothes for dinner, comfortable shoes for walking and a warm layer for cool evenings. A light jacket and sun protection are useful all year.

Bring a camera or two — the valleys are made for photographs — and anything you would like to celebrate with, such as a toast or a keepsake.', inclusions = '["Luxury lodge accommodation, with private villas where available","Meals as per the itinerary — breakfast, lunch and dinner","A private licensed cultural guide throughout","A private vehicle with driver for the whole journey","All monument and museum entrance fees"]', exclusions = '["International flights to and from Bhutan","The Sustainable Development Fee ($100 per person per night), billed separately","Travel insurance","Spa treatments, premium drinks and gratuities"]', faqs = '[{"question":"Can you arrange a surprise?","answer":"Yes. Flowers, a private dinner, a cake or a quiet word with the lodge team can all be arranged. Tell us what you have in mind."},{"question":"Is the Tiger’s Nest hike required?","answer":"No, it is optional. If you skip it, we can fill the day with a spa treatment or a village walk."},{"question":"When is the best time for a honeymoon?","answer":"Spring and autumn offer clear skies and mild temperatures. Winter is quiet and sunny in the valleys."}]', districts = '["Paro","Thimphu","Punakha","Wangdue Phodrang"]', cost_title = 'Package Cost', cost_text = 'On top of the Sustainable Development Fee of $100 per person per night (see our [Tariff page](/tariff)), there''s an additional cost covering accommodation, meals, entrance fees, your guide and a private tour vehicle. Send us an enquiry below and we''ll shape a package to your dates, budget and interests.', seo_description = 'Eight romantic days across Bhutan’s western valleys: private picnics, a temple blessing for couples and quiet evenings at the finest lodges.', updated_at = datetime('now') WHERE slug = 'luxury-honeymoon-package';
DELETE FROM itinerary_days WHERE tour_id = (SELECT id FROM tours WHERE slug = 'luxury-honeymoon-package');

UPDATE tours SET has_page = 1, summary = 'Seven days in restored farmhouses and heritage lodges across Paro, Thimphu and Punakha, staying where Bhutanese families have always lived.', overview_title = 'Tour Overview', overview = 'Bhutan''s traditional houses are works of craft: rammed-earth walls, carved wood windows, a prayer room under the roof. This journey stays in restored heritage lodges and farmhouses across Paro, Thimphu and Punakha, so the places you sleep are as much a part of the trip as the temples you visit.

Expect a gentler pace than a conventional tour: a hot stone bath in the evening, a meal cooked by the household, a walk through rice fields in the morning. Between stays you see the great dzongs and museums, and learn how the traditional arts are kept alive. It is a good fit for travellers who love architecture, food and craft.', highlights = '["Stay in restored farmhouses and heritage lodges","Hot stone baths and home-cooked meals with the host family","Folk Heritage Museum and Royal Textile Academy in Thimphu","Punakha Dzong and the walk to Chimi Lhakhang","See how the traditional arts are taught at the Zorig Chusum institute","Dochula pass with its 108 memorial chortens"]', facts = '[{"icon":"pin","label":"Destinations","value":"Paro, Thimphu, Punakha"},{"icon":"sun","label":"Best Season","value":"March–May & September–November"},{"icon":"mountain","label":"Max Altitude","value":"2,320m — highest overnight stay (Thimphu)"},{"icon":"bag","label":"Accommodation","value":"Heritage lodges and restored farmhouses"},{"icon":"meal","label":"Meals","value":"Full board — breakfast, lunch, dinner"},{"icon":"truck","label":"Transport","value":"Private SUV with driver"}]', facts_note = 'Use this as a general guide to the journey. The itinerary is further customized around the season, your interests, group size and preferred duration once you enquire.', pack_title = 'What To Pack', pack_text = 'Bring modest, comfortable clothes — shoulders and knees covered for temples and homes — and shoes that slip on and off easily. Evenings are cool in farmhouses, so pack a warm layer.

A small gift for your hosts is a nice gesture; your guide can suggest what is appropriate.', inclusions = '["Stays in heritage lodges and restored farmhouses","Meals as per the itinerary — breakfast, lunch and dinner","A private licensed cultural guide throughout","A private vehicle with driver for the whole journey","All monument and museum entrance fees"]', exclusions = '["International flights to and from Bhutan","The Sustainable Development Fee ($100 per person per night), billed separately","Travel insurance","Spa treatments, premium drinks and gratuities"]', faqs = '[{"question":"How comfortable are the farmhouses?","answer":"The farmhouses we use are restored with private bathrooms and comfortable beds while keeping their traditional character. We tell you exactly what to expect at each stop."},{"question":"Can we meet the host families?","answer":"Yes. Meals and evenings are often shared with the household, and your guide helps with introductions and translation."},{"question":"Is the programme physically demanding?","answer":"No. There is some walking in villages and temple grounds but no hard hiking. The Tiger’s Nest hike can be added if you like."}]', districts = '["Paro","Thimphu","Punakha"]', cost_title = 'Package Cost', cost_text = 'On top of the Sustainable Development Fee of $100 per person per night (see our [Tariff page](/tariff)), there''s an additional cost covering accommodation, meals, entrance fees, your guide and a private tour vehicle. Send us an enquiry below and we''ll shape a package to your dates, budget and interests.', seo_description = 'Seven days in restored farmhouses and heritage lodges across Paro, Thimphu and Punakha, staying where Bhutanese families have always lived.', updated_at = datetime('now') WHERE slug = 'heritage-lodge-tour';
DELETE FROM itinerary_days WHERE tour_id = (SELECT id FROM tours WHERE slug = 'heritage-lodge-tour');

UPDATE tours SET has_page = 1, summary = 'Seven days linking Bhutan’s valleys by private helicopter — scenic flights, lodge stays and a day of Himalayan views from above.', overview_title = 'Tour Overview', overview = 'Roads in Bhutan are slow and winding, which is part of the charm, but a helicopter turns a four-hour drive into a twenty-minute flight and shows you the country from a very different angle. This journey uses private helicopter transfers between valleys wherever permitted, so you spend your time at the lodges and monasteries and not in the car.

Flights are weather-dependent and subject to permits, so the plan is flexible: if the sky is clear you fly, and if not you drive and nothing is lost. Between flights the days follow the western valleys, with time at the lodges, a hike to Tiger''s Nest and an afternoon in each valley.', highlights = '["Private helicopter transfers between valleys, where permitted","A scenic flight over the Himalayan ridgeline","Cross-valley views of dzongs, monasteries and glacial lakes","Hike to Tiger’s Nest Monastery on the ground","Time at each lodge with no long drives","Flexible plan: roads as backup if weather closes in"]', facts = '[{"icon":"pin","label":"Destinations","value":"Paro, Thimphu, Punakha, Gangtey, Bumthang"},{"icon":"sun","label":"Best Season","value":"March–May & October–November"},{"icon":"mountain","label":"Max Altitude","value":"3,100m — Dochula and the passes crossed by air"},{"icon":"bag","label":"Accommodation","value":"Luxury lodges"},{"icon":"meal","label":"Meals","value":"Full board — breakfast, lunch, dinner"},{"icon":"truck","label":"Transport","value":"Private helicopter (where permitted) with SUV backup"}]', facts_note = 'Use this as a general guide to the journey. The itinerary is further customized around the season, your interests, group size and preferred duration once you enquire.', pack_title = 'What To Pack', pack_text = 'Helicopters have a strict weight allowance, so pack light: soft bags are best, and your guide can arrange for larger luggage to travel by road. Bring layers — it is colder in the air than on the ground — and sunglasses and sun protection.

Comfortable shoes for temple courtyards and the Tiger’s Nest path, a warm jacket and a camera with a wide-angle lens complete the list.', inclusions = '["Luxury lodge accommodation throughout","Meals as per the itinerary — breakfast, lunch and dinner","A private licensed cultural guide throughout","A private vehicle with driver for the whole journey","All monument and museum entrance fees"]', exclusions = '["International flights to and from Bhutan","The Sustainable Development Fee ($100 per person per night), billed separately","Travel insurance","Spa treatments, premium drinks and gratuities","Helicopter charters, which are quoted separately"]', faqs = '[{"question":"Are helicopter flights guaranteed?","answer":"No. They depend on the weather and on permits. If conditions don’t allow, the journey continues by road, and we plan the itinerary so little is lost."},{"question":"How much luggage can I bring?","answer":"Helicopters have a strict weight limit, so pack light. We can send larger bags by road to meet you."},{"question":"Is a helicopter flight safe?","answer":"Flights are operated by licensed operators with experienced mountain pilots, and are only flown when conditions are safe. We discuss details when you enquire."}]', districts = '["Paro","Thimphu","Punakha","Wangdue Phodrang","Bumthang"]', cost_title = 'Package Cost', cost_text = 'On top of the Sustainable Development Fee of $100 per person per night (see our [Tariff page](/tariff)), there''s an additional cost covering accommodation, meals, entrance fees, your guide and a private tour vehicle. Send us an enquiry below and we''ll shape a package to your dates, budget and interests.', seo_description = 'Seven days linking Bhutan’s valleys by private helicopter — scenic flights, lodge stays and a day of Himalayan views from above.', updated_at = datetime('now') WHERE slug = 'private-helicopter-lodge-tour';
DELETE FROM itinerary_days WHERE tour_id = (SELECT id FROM tours WHERE slug = 'private-helicopter-lodge-tour');
