INSERT INTO itinerary_days (tour_id, day_number, title, description, driving, elevation, attractions, overnight) VALUES ((SELECT id FROM tours WHERE slug = 'amankora-journey'), 1, 'Arrive In Paro', 'The first gift from Bhutan is the cool, clean air as you step off the plane. After visa formalities your guide welcomes you in the traditional way and takes you to your lodge, where the afternoon is yours.', 'Airport to lodge: 7 km / 15 to 20 mins', '2,200m / 7,218ft', '["Welcome at Paro airport","Check in and settle into your lodge","Welcome dinner"]', 'Overnight at the lodge in Paro');
INSERT INTO itinerary_days (tour_id, day_number, title, description, driving, elevation, attractions, overnight) VALUES ((SELECT id FROM tours WHERE slug = 'amankora-journey'), 2, 'Tiger’s Nest Hike', 'An early start for the cliffside climb to Taktsang, paced to your own speed, ending with a private blessing inside the monastery. Return to the lodge for a long, restful afternoon.', 'Lodge to trailhead: 12 km / 20 to 30 mins', 'Taktsang 3,120m / 10,236ft', '["Hike to the Taktsang (Tiger’s Nest) Monastery","Private blessing with a resident monk","Lunch at the viewpoint cafeteria"]', 'Overnight at the lodge in Paro');
INSERT INTO itinerary_days (tour_id, day_number, title, description, driving, elevation, attractions, overnight) VALUES ((SELECT id FROM tours WHERE slug = 'amankora-journey'), 3, 'Paro To Thimphu', 'Drive to the capital, with a stop at Tachog Lhakhang and its iron-chain bridge on the way if time allows.', '54 km / 1 to 1.5 hrs', '2,320m / 7,612ft', '["Tachog Lhakhang","Memorial Chorten","Buddha Dordenma"]', 'Overnight at the lodge in Thimphu');
INSERT INTO itinerary_days (tour_id, day_number, title, description, driving, elevation, attractions, overnight) VALUES ((SELECT id FROM tours WHERE slug = 'amankora-journey'), 4, 'Over Dochula Pass To Punakha', 'Climb out of Thimphu to Dochula pass and its 108 memorial chortens, with Himalayan views on a clear morning, then descend into the warm Punakha valley.', '77 km / 2.5 to 3 hrs', 'Dochula 3,100m / 10,171ft; Punakha 1,200m / 3,937ft', '["Dochula Pass and the 108 Druk Wangyal Chortens","Chimi Lhakhang, the temple of fertility","Punakha Dzong at sunset"]', 'Overnight at the lodge in Punakha');
INSERT INTO itinerary_days (tour_id, day_number, title, description, driving, elevation, attractions, overnight) VALUES ((SELECT id FROM tours WHERE slug = 'amankora-journey'), 5, 'A Day In Punakha', 'A slower day in the valley: Punakha Dzong, a walk across the long suspension bridge, and an afternoon by the river at the lodge.', 'Local — under 30 mins between stops', '1,200m / 3,937ft', '["Punakha Dzong","Punakha suspension bridge","Optional river walk or rafting"]', 'Overnight at the lodge in Punakha');
INSERT INTO itinerary_days (tour_id, day_number, title, description, driving, elevation, attractions, overnight) VALUES ((SELECT id FROM tours WHERE slug = 'amankora-journey'), 6, 'Punakha To Gangtey', 'Drive through Wangdue Phodrang and up into the Phobjikha valley, a wide glacial bowl and the winter home of black-necked cranes.', '78 km / 3 hrs', 'Gangtey 2,900m / 9,514ft', '["Wangdue Phodrang","Gangtey Goenpa","Phobjikha valley"]', 'Overnight at the lodge in Gangtey');
INSERT INTO itinerary_days (tour_id, day_number, title, description, driving, elevation, attractions, overnight) VALUES ((SELECT id FROM tours WHERE slug = 'amankora-journey'), 7, 'A Day In The Phobjikha Valley', 'Visit Gangtey Goenpa and take an easy nature walk across the valley floor. In winter, look for the black-necked cranes that spend the season here.', 'Local — under 20 mins', '2,900m / 9,514ft', '["Gangtey Goenpa","Gangtey Nature Trail","Black-necked Crane Information Centre"]', 'Overnight at the lodge in Gangtey');
INSERT INTO itinerary_days (tour_id, day_number, title, description, driving, elevation, attractions, overnight) VALUES ((SELECT id FROM tours WHERE slug = 'amankora-journey'), 8, 'Gangtey To Thimphu', 'Return west through Wangdue Phodrang and over Dochula pass, with a long lunch stop on the way.', '140 km / 5 hrs', '2,320m / 7,612ft', '["Dochula Pass on the return","Lunch with a view","Evening at the lodge"]', 'Overnight at the lodge in Thimphu');
INSERT INTO itinerary_days (tour_id, day_number, title, description, driving, elevation, attractions, overnight) VALUES ((SELECT id FROM tours WHERE slug = 'amankora-journey'), 9, 'Thimphu To Paro And Departure', 'A last morning in the capital, then the drive to Paro for your onward flight.', '54 km / 1 to 1.5 hrs', '2,235m / 7,333ft', '["Morning in Thimphu","Private transfer to Paro International Airport"]', '');
